var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMemoryCache(options =>
{
    options.SizeLimit = 1024; // Limit total cache size in arbitrary units
    options.CompactionPercentage = 0.2; // Remove 20% when at capacity
});

var app = builder.Build();

public class ProductService
{
    private readonly IMemoryCache _cache;
    private const string CacheKey = "all-products";

    public ProductService(IMemoryCache cache)
    {
        _cache = cache;
    }

    public async Task<List<Product>> GetAllProductsAsync()
    {
        if (!_cache.TryGetValue(CacheKey, out List<Product> products))
        {
            products = await _dbContext.Products.ToListAsync();

            var cacheEntryOptions = new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10),
                SlidingExpiration = TimeSpan.FromMinutes(2),
                Priority = CacheItemPriority.High,
                Size = 1
            }
            .RegisterPostEvictionCallback(
                (key, value, reason, state) =>
                {
                    Console.WriteLine($"Cache entry evicted: {key}. Reason: {reason}");
                });

            _cache.Set(CacheKey, products, cacheEntryOptions);
        }

        return products;
    }
}
